import pandas as pd
import numpy as np
from sklearn.ensemble import RandomForestRegressor, ExtraTreesRegressor, GradientBoostingRegressor, HistGradientBoostingRegressor

df = pd.read_csv('b3_fatigue_data.csv')
features = [c for c in df.columns if c != 'target']
X = df[features].values
y = df['target'].values

models = {
    'RF': RandomForestRegressor(n_estimators=300, max_depth=12, min_samples_leaf=2, random_state=42),
    'ET': ExtraTreesRegressor(n_estimators=300, max_depth=12, min_samples_leaf=2, random_state=42),
    'GB': GradientBoostingRegressor(n_estimators=300, max_depth=4, learning_rate=0.05, random_state=42),
    'HGB': HistGradientBoostingRegressor(max_depth=6, learning_rate=0.08, max_iter=300, random_state=42),
}
fitted = {n: m.fit(X, y) for n, m in models.items()}

top = df.iloc[299][features].copy()

print("=== NT sweep on top composition ===")
for nt in [825, 845, 865, 870, 885, 900, 910, 915, 920, 925, 930]:
    xp = top.copy(); xp['NT'] = nt
    preds = {n: m.predict(xp.values.reshape(1,-1))[0] for n,m in fitted.items()}
    print(f"NT={nt}: " + " ".join(f"{n}={p:.1f}" for n,p in preds.items()) + f" avg={np.mean(list(preds.values())):.1f}")

print("\n=== CT sweep ===")
for ct in [30, 100, 200, 400, 500, 600, 700, 800, 850, 883.5, 900, 930]:
    xp = top.copy(); xp['CT'] = ct
    preds = {n: m.predict(xp.values.reshape(1,-1))[0] for n,m in fitted.items()}
    print(f"CT={ct}: " + " ".join(f"{n}={p:.1f}" for n,p in preds.items()) + f" avg={np.mean(list(preds.values())):.1f}")

print("\n=== TT sweep ===")
for tt in [30, 100, 140, 152, 160, 168, 180, 200, 250, 300, 420, 500, 600]:
    xp = top.copy(); xp['TT'] = tt
    preds = {n: m.predict(xp.values.reshape(1,-1))[0] for n,m in fitted.items()}
    print(f"TT={tt}: " + " ".join(f"{n}={p:.1f}" for n,p in preds.items()) + f" avg={np.mean(list(preds.values())):.1f}")

print("\n=== QmT sweep ===")
for q in [30, 50, 60, 80, 100, 120, 133, 140]:
    xp = top.copy(); xp['QmT'] = q
    preds = {n: m.predict(xp.values.reshape(1,-1))[0] for n,m in fitted.items()}
    print(f"QmT={q}: " + " ".join(f"{n}={p:.1f}" for n,p in preds.items()) + f" avg={np.mean(list(preds.values())):.1f}")

print("\n=== Ct sweep ===")
for c in [0, 90, 140, 200, 300, 340, 400, 450, 470, 500, 513, 540]:
    xp = top.copy(); xp['Ct'] = c
    preds = {n: m.predict(xp.values.reshape(1,-1))[0] for n,m in fitted.items()}
    print(f"Ct={c}: " + " ".join(f"{n}={p:.1f}" for n,p in preds.items()) + f" avg={np.mean(list(preds.values())):.1f}")

print("\n=== Feature importances RF ===")
imp = fitted['RF'].feature_importances_
for f,i in sorted(zip(features, imp), key=lambda x:-x[1]):
    print(f"{f:10s} {i:.4f}")
